  TEST_ASSERT_FALSE(overlay_fps_visible(&ov));
  TEST_ASSERT_FALSE(overlay_battery_visible(&ov));
  overlay_cycle_info(&ov);
  TEST_ASSERT_TRUE(overlay_fps_visible(&ov));
  TEST_ASSERT_FALSE(overlay_battery_visible(&ov));
  overlay_cycle_info(&ov);
  TEST_ASSERT_FALSE(overlay_fps_visible(&ov));
  TEST_ASSERT_TRUE(overlay_battery_visible(&ov));
  overlay_cycle_info(&ov);
  TEST_ASSERT_FALSE(overlay_fps_visible(&ov));
  TEST_ASSERT_FALSE(overlay_battery_visible(&ov));
