{
    if (value == nullptr) {
        M5PM1_LOG_E(TAG_I2C, "Read16 Reg[0x%02X] failed: null value", reg);
        return false;
    }

    _checkAutoWake();
    bool success = false;
    for (int attempt = 0; attempt < M5PM1_I2C_RETRY_COUNT; ++attempt) {
#ifdef ARDUINO
#if M5PM1_HAS_M5UNIFIED_I2C
